"""costCoeffRemain operator candidate (dispatch-level, no encoder flow
changes). The reference is a C scalar loop; this variant unrolls the
idx<8 / idx>=8 base-level split and uses clz directly."""


def emit(func_name="dynopt_cost_coeff_remain_sve2"):
    return r"""\
// Generated by tools/emit_cost_remain_sve2_shared.py -- do not edit.
#include <stdint.h>
#include <stddef.h>

extern "C" uint32_t dynopt_cost_coeff_remain_sve2(
    uint16_t* absCoeff, int numNonZero, int idx)
{
    uint32_t goRice = 0;
    uint32_t sum = 0;
    int baseLevel = 3;
    while (idx < numNonZero)
    {
        if (idx >= 8)
            baseLevel = 1;
        const int codeNumber = (int)absCoeff[idx] - baseLevel;
        if (codeNumber >= 0)
        {
            uint32_t cn = ((uint32_t)codeNumber >> goRice) - 3;
            uint32_t length = 0;
            if ((int32_t)cn >= 0)
            {
                length = (uint32_t)(31 - __builtin_clz(cn + 1));
                cn = length + length;
            }
            sum += 4 + goRice + cn;
            if (absCoeff[idx] > (3u << goRice))
                goRice = (goRice + 1) - (goRice >> 2);
        }
        baseLevel = 2;
        idx++;
    }
    return sum;
}
""".replace("dynopt_cost_coeff_remain_sve2", func_name)


def emit_combo(combo):
    return emit()


def _dfa_step(g, base, v):
    """Exactly reproduce one costCoeffRemain_c iteration (dct.cpp)."""
    code = v - base
    if code < 0:
        return (0, g)
    cn = (code >> g) - 3
    if cn < 0:
        add = 4 + g + cn
    else:
        length = (cn + 1).bit_length() - 1
        add = 4 + g + length + length
    ng = g
    if v > (3 << g):
        ng = (g + 1) - (g >> 2)
    return (add, ng)


def emit_dfa(func_name="dynopt_cost_coeff_remain_sve2"):
    """DFA table variant (round-0032). Real 920B trace: absCoeff is 1/2 in
    75% of coefficients and <=10 covers 99.5%, so a (goRice 0..4) x
    (phase: first idx<8 base3 / later idx<8 base2 / idx>=8 base1) x
    (value 0..255) table gives the per-coefficient add + next state in
    two byte loads. Values >= 256 fall back to the reference formula.
    """
    add_tbl = []
    nxt_tbl = []
    for g in range(5):
        for phase in range(3):
            base = 3 if phase == 0 else (1 if phase == 2 else 2)
            for v in range(256):
                add, ng = _dfa_step(g, base, v)
                add_tbl.append(add)
                nxt_tbl.append(ng)
    add_src = ", ".join(str(x) for x in add_tbl)
    nxt_src = ", ".join(str(x) for x in nxt_tbl)
    return r"""\
// Generated by tools/emit_cost_remain_sve2_shared.py -- do not edit.
#include <stdint.h>
#include <stddef.h>

static const uint8_t DYNOPT_REM_ADD[5][3][256] = {
    %s
};
static const uint8_t DYNOPT_REM_NEXT[5][3][256] = {
    %s
};

extern "C" uint32_t %s(
    uint16_t* absCoeff, int numNonZero, int idx)
{
    uint32_t goRice = 0;
    uint32_t sum = 0;
    int phase = (idx >= 8) ? 2 : 0;
    while (idx < numNonZero)
    {
        const uint32_t v = absCoeff[idx];
        if (v < 256)
        {
            sum += DYNOPT_REM_ADD[goRice][phase][v];
            goRice = DYNOPT_REM_NEXT[goRice][phase][v];
        }
        else
        {
            const int baseLevel = phase == 0 ? 3
                               : phase == 2 ? 1 : 2;
            const int codeNumber = (int)v - baseLevel;
            if (codeNumber >= 0)
            {
                uint32_t cn = ((uint32_t)codeNumber >> goRice) - 3;
                uint32_t length = 0;
                if ((int32_t)cn >= 0)
                {
                    length = (uint32_t)(31 - __builtin_clz(cn + 1));
                    cn = length + length;
                }
                sum += 4 + goRice + cn;
                if (v > (3u << goRice))
                    goRice = (goRice + 1) - (goRice >> 2);
            }
        }
        idx++;
        phase = (idx >= 8) ? 2 : 1;
    }
    return sum;
}
""" % (add_src, nxt_src, func_name)
